#!/usr/bin/env python3
"""Check internal and external links in Markdown files.

Usage: linkcheck.py <repo_root> <out_json> <file_or_dir>...
Internal: target file exists; #anchor matches a GitHub-style heading slug (or an explicit
<a id/name>), and #Lnn line anchors are within the file length.
External: HTTP HEAD, then GET on failure; redirects followed; 30 s timeout.
"""
import concurrent.futures as cf
import json
import os
import re
import sys
import urllib.error
import urllib.parse
import urllib.request

root, out_json, targets = sys.argv[1], sys.argv[2], sys.argv[3:]
os.chdir(root)

files = []
for t in targets:
    if os.path.isdir(t):
        for dp, _, fns in os.walk(t):
            files += [os.path.join(dp, f) for f in fns if f.endswith(".md")]
    else:
        files.append(t)
files.sort()

LINK = re.compile(r"(?<!!)\[(?:[^\[\]]|\[[^\]]*\])*\]\(\s*<?([^)\s>]+)>?(?:\s+\"[^\"]*\")?\s*\)")
IMG = re.compile(r"!\[[^\]]*\]\(\s*<?([^)\s>]+)>?\s*\)")
REF = re.compile(r"^\s*\[[^\]]+\]:\s*(\S+)", re.M)
BARE = re.compile(r"(?<![(<\[`])\bhttps?://[^\s)>\]`\"']+")


def strip_code(text):
    # remove fenced blocks and inline code so example URLs in code are not checked
    text = re.sub(r"```.*?```", lambda m: "\n" * m.group(0).count("\n"), text, flags=re.S)
    return re.sub(r"`[^`\n]*`", "", text)


def slug(h):
    h = re.sub(r"<[^>]+>", "", h).strip().lower()
    h = re.sub(r"[`*_~]", "", h) if False else h.replace("`", "")
    h = re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", h)
    h = re.sub(r"[^\w\- ]", "", h, flags=re.U)
    return h.replace(" ", "-")


anchor_cache = {}


def anchors(path):
    if path in anchor_cache:
        return anchor_cache[path]
    text = open(path, encoding="utf-8").read()
    body = re.sub(r"```.*?```", "", text, flags=re.S)
    seen, out = {}, set()
    for m in re.finditer(r"^#{1,6}\s+(.+?)\s*#*\s*$", body, re.M):
        s = slug(m.group(1))
        n = seen.get(s, 0)
        out.add(s if n == 0 else f"{s}-{n}")
        seen[s] = n + 1
    out |= set(re.findall(r"<a\s+(?:id|name)=\"([^\"]+)\"", text))
    anchor_cache[path] = (out, text.count("\n") + 1)
    return anchor_cache[path]


internal, external = [], {}
for f in files:
    raw = open(f, encoding="utf-8").read()
    text = strip_code(raw)
    for lineno, line in enumerate(text.split("\n"), 1):
        urls = LINK.findall(line) + IMG.findall(line) + REF.findall(line)
        urls += [u.rstrip(".,;:") for u in BARE.findall(line)]
        for u in urls:
            if u.startswith(("http://", "https://")):
                external.setdefault(u, []).append(f"{f}:{lineno}")
            elif u.startswith("mailto:"):
                continue
            else:
                internal.append((f, lineno, u))

results = {"files": files, "internal": [], "external": []}
for f, ln, u in internal:
    path, _, frag = u.partition("#")
    path = urllib.parse.unquote(path)
    tgt = os.path.normpath(os.path.join(os.path.dirname(f), path)) if path else f
    status = "ok"
    if not os.path.exists(tgt):
        status = "missing file"
    elif frag and os.path.isfile(tgt) and tgt.endswith(".md"):
        names, nlines = anchors(tgt)
        m = re.fullmatch(r"L(\d+)(?:-L(\d+))?", frag)
        if m:
            if int(m.group(2) or m.group(1)) > nlines:
                status = f"line anchor beyond EOF ({nlines} lines)"
        elif frag.lower() not in names:
            status = "missing anchor"
    elif frag and os.path.isfile(tgt):
        m = re.fullmatch(r"L(\d+)(?:-L(\d+))?", frag)
        if m:
            nlines = open(tgt, encoding="utf-8", errors="replace").read().count("\n") + 1
            if int(m.group(2) or m.group(1)) > nlines:
                status = f"line anchor beyond EOF ({nlines} lines)"
    results["internal"].append({"src": f"{f}:{ln}", "link": u, "status": status})

UA = {"User-Agent": "Mozilla/5.0 (X11; Linux x86_64) link-check", "Accept": "*/*"}


def fetch(u):
    last = None
    for method in ("HEAD", "GET"):
        try:
            req = urllib.request.Request(u.split("#")[0], headers=UA, method=method)
            with urllib.request.urlopen(req, timeout=30) as r:
                body = r.read(400000) if method == "GET" else b""
                final = r.geturl()
                frag = u.partition("#")[2]
                note = ""
                if frag and method == "GET" and b"<" in body:
                    if frag.encode() not in body and urllib.parse.unquote(frag).encode() not in body:
                        note = "fragment not found in first 400 KB"
                return {"url": u, "code": r.status, "final": final if final != u.split("#")[0] else "", "note": note}
        except urllib.error.HTTPError as e:
            last = {"url": u, "code": e.code, "final": "", "note": str(e.reason)}
            if method == "HEAD":
                continue
        except Exception as e:  # noqa: BLE001
            last = {"url": u, "code": None, "final": "", "note": type(e).__name__ + ": " + str(e)[:120]}
            if method == "HEAD":
                continue
    return last


def fetch_get_for_fragment(u):
    r = fetch(u)
    if r and r["code"] == 200 and "#" in u and not r["note"]:
        # HEAD succeeded; fetch body to check fragment
        try:
            req = urllib.request.Request(u.split("#")[0], headers=UA)
            with urllib.request.urlopen(req, timeout=30) as resp:
                body = resp.read(2_000_000)
            frag = u.partition("#")[2]
