#!/usr/bin/env python3
"""Cross-reference tool identifiers used in docs/ and examples/ against work/02-research.md.

Usage: xref.py <repo_root> <out_json>
Extracts code-formatted identifiers (flags, settings keys, env vars, IAM condition keys,
snake_case keywords, permission-rule tools) from Markdown, plus config keys from the
example JSON/YAML files. For each term reports where a source exists.
"""
import collections
import glob
import json
import os
import re
import subprocess
import sys

root, out = sys.argv[1], sys.argv[2]
os.chdir(root)
tracked = subprocess.check_output(["git", "ls-files"], text=True).split()

R02 = open("work/02-research.md", encoding="utf-8").read()
OTHER = {p: open(p, encoding="utf-8").read() for p in
         ["work/09-fix-research.md", "work/07-review.md", "work/08-fix-proposals.md",
          "work/03-options.md", "work/01-problem-framing.md", "work/05-deliverable-plan.md"]}
SCHEMA = {p: open(p, encoding="utf-8").read() for p in glob.glob("examples/schemas/*.json")}

terms = collections.defaultdict(lambda: {"cat": None, "uses": []})


def add(term, cat, where):
    t = terms[term]
    t["cat"] = t["cat"] or cat
    if len(t["uses"]) < 400:
        t["uses"].append(where)


PLACEHOLDER = re.compile(r"^<.*>$|EXAMPLE|PLACEHOLDER|_ID$|^AWS_ACCOUNT")
SKIP_SNAKE = {"run_in_background"}


def classify(tok):
    if re.fullmatch(r"--?[a-zA-Z][\w-]*", tok):
        return "flag"
    if re.fullmatch(r"[A-Z][A-Z0-9]*(_[A-Z0-9]+)+", tok) and not PLACEHOLDER.search(tok):
        return "env/const"
    if re.fullmatch(r"(aws|iam|sts|s3|ec2|kms|lambda|rds|sso|organizations|token\.actions\.githubusercontent\.com|identitystore|logs|cloudtrail)"
                    r":[A-Za-z][\w/\-{}$.*]*", tok):
        return "iam-key-or-action"
    if re.fullmatch(r"[a-z][a-z0-9]*([A-Z][a-z0-9]*)+(\.[a-zA-Z]\w*)*", tok):
        return "camelCase key"
    if re.fullmatch(r"[a-z][a-zA-Z0-9]*(\.[a-zA-Z][\w$-]*)+", tok) and not re.search(r"\.(md|json|ya?ml|py|ts|sh|txt|svg|mmd|toml|js|com|org|io)$", tok):
        return "dotted key"
    if re.fullmatch(r"[a-z]+(_[a-z0-9]+)+", tok) and tok not in SKIP_SNAKE:
        return "snake_case keyword"
    if re.fullmatch(r"(Bash|Read|Edit|Write|WebFetch|WebSearch|mcp__\w+)\(.*\)", tok):
        return "permission rule"
    return None


md = [f for f in tracked if f.endswith(".md") and (f.startswith("docs/") or f.startswith("examples/") or f == "README.md")]
for f in md:
    text = open(f, encoding="utf-8").read()
    for ln, line in enumerate(text.split("\n"), 1):
        for span in re.findall(r"`([^`\n]+)`", line):
            span = span.strip()
            cat = classify(span)
            if cat:
                add(span, cat, f"{f}:{ln}")
            # flags inside commands
            for fl in re.findall(r"(?<![\w-])(--[a-zA-Z][\w-]*)", span):
                if fl != span:
                    add(fl, "flag", f"{f}:{ln}")
            # env vars inside commands
            for ev in re.findall(r"\b([A-Z][A-Z0-9]*(?:_[A-Z0-9]+)+)\b", span):
                if ev != span and not PLACEHOLDER.search(ev):
                    add(ev, "env/const", f"{f}:{ln}")


# flags in workflow run: lines and shell scripts in examples
for f in [x for x in tracked if x.startswith("examples/github/workflows/")]:
    for ln, line in enumerate(open(f, encoding="utf-8").read().split("\n"), 1):
        if line.lstrip().startswith("#"):
            continue
        for fl in re.findall(r"(?<![\w-])(--[a-zA-Z][\w-]*)", line):
            add(fl, "flag", f"{f}:{ln}")
        m = re.match(r"\s*(?:-\s+)?([a-z][\w-]*):", line)


def walk(o, path, f, cat):
    if isinstance(o, dict):
        for k, v in o.items():
            if k.startswith("$") and k != "$defaults":
                continue
            add(k, cat, f"{f}:{'.'.join(path + [k])}")
            walk(v, path + [k], f, cat)
    elif isinstance(o, list):
        for v in o:
            if isinstance(v, str):
                cls = classify(v)
                if cls == "permission rule":
                    add(re.match(r"[\w_]+", v).group(0) + "(…)", "permission rule tool", f"{f}:{'.'.join(path)}")
            walk(v, path, f, cat)


for f in [x for x in tracked if x.startswith("examples/claude/") and x.endswith(".json")]:
    walk(json.load(open(f)), [], f, "claude config key")
for f in [x for x in tracked if x.startswith("examples/aws/") and x.endswith(".json")]:
    d = json.load(open(f))
    for st in (d.get("Statement") or (json.loads(d["InlinePolicy"]) if isinstance(d.get("InlinePolicy"), str) else d.get("InlinePolicy", {})).get("Statement", [])):
        for op, kv in (st.get("Condition") or {}).items():
            add(op, "IAM condition operator", f)
            for k in kv:
                add(k, "IAM condition key", f)
    if "Statement" not in d:
        walk(d, [], f, "aws config key")
for f in [x for x in tracked if x.startswith("examples/k0s/") or x.endswith("PulumiPolicy.yaml")]:
    import yaml
    for doc in yaml.safe_load_all(open(f)):
        walk(doc, [], f, "yaml config key")


def found(term):
    variants = {term}
    if term.startswith("--"):
        variants.add(term)
    if term.endswith("(…)"):
        variants = {term[:-3] + "("}
    r = {}
    r["02-research"] = any(v in R02 for v in variants)
    r["other-work"] = sorted({os.path.basename(p) for p, t in OTHER.items() if any(v in t for v in variants)})
    r["schema"] = sorted({os.path.basename(p) for p, t in SCHEMA.items() if any(f'"{v}"' in t for v in variants)})
    # a 📖 link on the same doc line as a use
    link_lines = []
    for u in terms[term]["uses"]:
        m = re.match(r"(.+\.md):(\d+)$", u)
        if m:
            line = open(m.group(1), encoding="utf-8").read().split("\n")[int(m.group(2)) - 1]
            if "📖" in line and "http" in line:
                link_lines.append(u)
    r["inline-📖-link"] = link_lines[:3]
    return r


rows = []
for term, t in sorted(terms.items()):
    r = found(term)
    files = sorted({u.split(":")[0] for u in t["uses"]})
    rows.append({"term": term, "cat": t["cat"], "n": len(t["uses"]), "files": files,
                 "first": t["uses"][0], **r})
json.dump(rows, open(out, "w"), indent=1, ensure_ascii=False)
c = collections.Counter((r["cat"], r["02-research"]) for r in rows)
print("terms:", len(rows))
for (cat, ok), n in sorted(c.items()):
    print(f"  {cat:24} in 02-research={ok!s:5} {n}")
none = [r for r in rows if not r["02-research"] and not r["other-work"] and not r["schema"] and not r["inline-📖-link"]]
print("no source anywhere (02, other work notes, schemas, inline 📖 link):", len(none))

